/* ---- drawing helpers for this lesson (prefixed OF_ so nothing clashes with the engine) ---- */
const OF_F='font-family="Nunito Sans, sans-serif"';
const OF_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${OF_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const OF_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OF_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const OF_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5', OF_GEL='#C5F6FA';
/* subscript inside on-screen text (tabs keep the tspan whole when a line wraps) */
const OF_sb=t=>`<tspan\tbaseline-shift="-0.2em"\tfont-size="72%">${t}</tspan>`;
const OF_PIN='P'+OF_sb('in'), OF_POUT='P'+OF_sb('out');
/* a fiber drawn side-on: end face at x0 (left end) or x1 (right end), core between yc-hc and yc+hc, cladding cw each side */
const OF_fiber=(x0,x1,yc,hc,cw)=>`<rect x="${x0}" y="${yc-hc-cw}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="2"/>`;
/* the book's numbers, computed once */
const OF_eta=x=>(2/Math.PI)*(Math.acos(x)-x*Math.sqrt(1-x*x));     // overlap of two equal step-index cores
const OF_dB=e=>-10*Math.log10(e);
/* MZM transfer curve of the worked example: Pout = 2.0 mW cos²(πV/8), V from 0 to 8 V, drawn from computed points */
const OF_mzP=V=>2.0*Math.cos(Math.PI*V/8)**2;
const OF_curve=(x0,y0,w,h,col,sw=4)=>{let p=[];for(let i=0;i<=80;i++){const V=i/10;p.push(`${(x0+w*V/8).toFixed(1)},${(y0-h*OF_mzP(V)/2).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${sw}" stroke-linejoin="round"/>`};
const OF_axes=(x0,y0,w,h,ticks=true)=>OF_L(x0,y0,x0+w,y0,'#ADB5BD',3)+OF_L(x0,y0,x0,y0-h-14,'#ADB5BD',3)+(ticks?[0,2,4,6,8].map(V=>OF_L(x0+w*V/8,y0,x0+w*V/8,y0+8,'#ADB5BD',3)+OF_T(x0+w*V/8,y0+32,V+' V',{fs:22,a:'middle',fill:OF_GREY})).join(''):'');
/* a Mach-Zehnder outline: input at (x0,yc), arms at yc±dy, output at x1 */
const OF_mz=(x0,x1,yc,dy,col,w=5)=>{const a=x0+(x1-x0)*.18,b=x0+(x1-x0)*.3,c=x0+(x1-x0)*.7,d=x0+(x1-x0)*.82;
 return `<polyline points="${x0},${yc} ${a},${yc} ${b},${yc-dy} ${c},${yc-dy} ${d},${yc} ${x1},${yc}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/><polyline points="${a},${yc} ${b},${yc+dy} ${c},${yc+dy} ${d},${yc}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* a sine wave from x0 to x1 about yc; k(x) gives the local wavelength */
const OF_wave=(x0,x1,yc,amp,lam,col,w=4)=>{let p=[],ph=0;for(let x=x0;x<=x1;x+=2){p.push(`${x},${(yc-amp*Math.sin(ph)).toFixed(1)}`);ph+=2*Math.PI*2/lam(x)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}"/>`};

